public function changeLineType(DataObjectInterface $dataObject)
    {
        $max = $dataObject->count();
        $delimiterFound = 0;

        $blockContent = [];

        for ($i = $this->lineNumber; $i < $max; $i++) {
            $currentLine = $dataObject->getLine($i);
            $lineContent = $currentLine->getContent();

            $this->createSkipLine($dataObject, $i);

            if ($this->isBlockDelimiterLine($lineContent)) {
                $this->setContentBlockKeyByContent($lineContent);
                $delimiterFound++;

                continue;
            }

            if ($delimiterFound > 1) {
                break;
            }

            $blockContent[] = $lineContent;
        }

        $content = $this->getSubBlockParsedContent($blockContent);

        $dataObject->saveAvailableBlock($this->contentBlockKey, $content);
    }

private function setInputFormat($if) : void
    {
        if ($if !== null) {
            if (is_array($if) === true) {
                $requiredKeys = ["name", "length", "check", "removeFormat", "format", "storageFormat"];

                foreach ($requiredKeys as $key) {
                    if (array_key_exists($key, $if) === false) {
                        $msg = "Lost required key in the given input format rule.";
                        throw new \InvalidArgumentException($msg);
                    } else {
                        $msg = null;
                        $kVal = $if[$key];
                        switch ($key) {
                            case "name":
                                if (is_string($kVal) === false || strlen($kVal) === 0) {
                                    $msg = "Invalid given \"$key\" of input format. Expected a not empty string.";
                                }
                                break;

                            case "length":
                                if (is_int($kVal) === false && $kVal !== null) {
                                    $msg = "Invalid given \"$key\" of input format. Expected integer or null.";
                                }
                                break;

                            case "check":
                            case "removeFormat":
                            case "format":
                            case "storageFormat":
                                if (is_callable($kVal) === false) {
                                    $msg = "Invalid given \"$key\" of input format. Expected callable.";
                                }
                                break;
                        }

                        if ($msg !== null) {
                            throw new \InvalidArgumentException($msg);
                        }
                    }
                }

                $this->inputFormat = [
                    "name"          => strtoupper($if["name"]),
                    "length"        => (($if["length"] === null) ? null : (int)$if["length"]),
                    "check"         => $if["check"],
                    "removeFormat"  => $if["removeFormat"],
                    "format"        => $if["format"],
                    "storageFormat" => $if["storageFormat"]
                ];
            } else {
                if (class_exists($if) === false) {
                    $if = "AeonDigital\\DataFormat\\Patterns\\" . str_replace(".", "\\", $if);
                }

                if (class_exists($if) === false) {
                    $msg = "The given \"inputFormat\" class does not exists.";
                    throw new \InvalidArgumentException($msg);
                } else {
                    $this->inputFormatReflection = new \ReflectionClass($if);

                    if ($this->isValidInputFormat($if) === false) {
                        $msg = "The given \"inputFormat\" class does not implements the interface \"AeonDigital\\DataFormat\\Interfaces\\iFormat\".";
                        throw new \InvalidArgumentException($msg);
                    }

                    $this->inputFormat = [
                        "name"          => $if,
                        "length"        => $if::MaxLength,
                        "check"         => $if . "::check",
                        "removeFormat"  => $if . "::removeFormat",
                        "format"        => $if . "::format",
                        "storageFormat" => $if . "::storageFormat"
                    ];
                }
            }
        }
    }

public function insert(PagerInterface $pager, array $options = array())
    {
        $pager->setMaxPerPage(empty($options['max_per_page']) ? 100 : $options['max_per_page']);

        $options = array_replace([
            'max_per_page' => $pager->getMaxPerPage(),
            'first_page' => $pager->getCurrentPage(),
            'last_page' => $pager->getNbPages(),
        ], $options);

        $pager->setCurrentPage($options['first_page']);

        $objectPersister = $this->registry->getPersister($options['indexName'], $options['typeName']);

        try {
            $event = new PrePersistEvent($pager, $objectPersister, $options);
            $this->dispatcher->dispatch(Events::PRE_PERSIST, $event);
            $pager = $event->getPager();
            $options = $event->getOptions();

            $lastPage = min($options['last_page'], $pager->getNbPages());
            $page = $pager->getCurrentPage();
            do {
                $pager->setCurrentPage($page);

                $this->insertPage($page, $pager, $objectPersister, $options);

                $page++;
            } while ($page <= $lastPage);
        } finally {
            $event = new PostPersistEvent($pager, $objectPersister, $options);
            $this->dispatcher->dispatch(Events::POST_PERSIST, $event);
        }
    }

